12	
13	/**
14	 * Validates the optional {@code postcode} against the owner's city.
15	 *
16	 * <p>Postcode is validated <strong>only when present</strong> and is optional when absent, so an owner
17	 * created without a postcode is still accepted. When supplied it must be four digits (enforced by the
18	 * schema pattern and re-checked defensively here) and, when the city maps to a known region, must fall
19	 * within that region's inclusive range per the fixed table:
20	 * NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit
21	 * postcode. An out-of-range postcode is rejected with 400 via {@link MethodArgumentNotValidException}.
22	 */
23	public class ValidatePostcode {
24	
25	    private static final Method SERVICE_METHOD;
26	
27	    static {
28	        try {
29	            SERVICE_METHOD = ValidatePostcode.class.getMethod("service", OwnerFieldsDto.class);
30	        }
31	        catch (NoSuchMethodException ex) {
32	            throw new ExceptionInInitializerError(ex);
33	        }
34	    }
35	
36	    /** Fixed city-to-region table, mirroring the read-time locality derivation. */
37	    private static final Map<String, String> CITY_REGION = Map.of(
38	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
39	
40	    /** Region to its inclusive 4-digit postcode range {low, high}. */
41	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
42	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
43	
44	    public void service(@Val OwnerFieldsDto request) throws MethodArgumentNotValidException {
45	        String postcode = request.getPostcode();
46	        if (postcode == null || postcode.isBlank()) {
47	            return; // optional when absent — nothing to validate
48	        }
49	        BindingResult binding = new BeanPropertyBindingResult(request, "ownerFieldsDto");
50	        if (!postcode.matches("[0-9]{4}")) {
51	            binding.rejectValue("postcode", "Pattern", "must be a 4-digit postcode");
52	        }
53	        else {
54	            String region = CITY_REGION.get(request.getCity());
55	            int[] range = region == null ? null : REGION_POSTCODES.get(region);
