204	     * lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
205	     * Two owners are the same identity only when their whole key matches, so two people who share a
206	     * surname (same {@link Soundex} code) and residence but have different telephones have distinct keys
207	     * — they are a soft match, not a hard duplicate. The surname contributes only via its Soundex code,
208	     * so trivially different spellings of the same-sounding name collide.
209	     */
210	    @Transient
211	    public String getIdentityKey() {
212	        String tel = this.telephone == null ? "" : this.telephone;
213	        String em = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
214	        String surname = Soundex.encode(this.getLastName());
215	        return sha256Hex(tel + "|" + em + "|" + surname);
