218	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
219	    private static String sha256Hex(String value) {
220	        try {
221	            byte[] digest = MessageDigest.getInstance("SHA-256")
222	                    .digest(value.getBytes(StandardCharsets.UTF_8));
223	            StringBuilder sb = new StringBuilder(digest.length * 2);
224	            for (byte b : digest) {
225	                sb.append(String.format("%02x", b));
226	            }
227	            return sb.toString();
228	        }
229	        catch (NoSuchAlgorithmException ex) {
230	            throw new IllegalStateException("SHA-256 not available", ex);
231	        }
232	    }
