134	    /** Single Luhn check digit (0-9) over the digits contained in {@code s}; non-digits are skipped. */
135	    private static int luhn(String s) {
136	        int sum = 0;
137	        boolean dbl = true;
138	        for (int i = s.length() - 1; i >= 0; i--) {
139	            char c = s.charAt(i);
140	            if (c < '0' || c > '9') {
141	                continue;
142	            }
143	            int d = c - '0';
144	            if (dbl) {
145	                d *= 2;
146	                if (d > 9) {
147	                    d -= 9;
148	                }
149	            }
150	            sum += d;
151	            dbl = !dbl;
152	        }
153	        return (10 - (sum % 10)) % 10;
154	    }
155	}
