12	/**
13	 * Emits an audit line to the dedicated {@code AUDIT} logger recording a successful owner
14	 * create. Runs after {@link SaveOwner} (so the owner id is assigned) and before the
15	 * responder. The line carries the owner id, the {@code memberId}, the
16	 * {@code registrationDate} and the {@code membershipLevel}.
17	 *
18	 * <p>Besides that human-readable line it emits an immutable structured {@link OwnerCreatedEvent}
19	 * as JSON to the same logger, with a {@code seq} that increases monotonically across creates.
20	 */
21	public class AuditOwnerCreated {
22	
23	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
24	
25	    private static final ObjectMapper MAPPER = new ObjectMapper();
26	
27	    /** Monotonically increasing sequence across all owner creates. */
28	    private static final AtomicLong SEQ = new AtomicLong();
29	
30	    public void service(@Val Owner owner) {
31	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
32	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
33	                owner.getMembershipLevel());
34	
35	        // The owner's primary identifier is the unified memberId.
36	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
37	                owner.getMemberId(), owner.getMembershipLevel(), OwnerCreatedEvent.OWNER_CREATED);
38	        AUDIT.info("{}", MAPPER.writeValueAsString(event));
39	    }
40	}
