1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	import java.util.Map;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
25	    @Mapping(target = "initials", expression = "java(initials(owner))")
26	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
31	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
32	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
33	    @Mapping(target = "bulkSignupWarning", ignore = true)
34	    @Mapping(target = "capacityWarning", ignore = true)
35	    @Mapping(target = "riskFlag", ignore = true)
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * The owner's canonical self link, derived at read time as {@code '/api/owners/'} followed by
40	     * the owner's id. Null when the owner or its id is absent, so the field is simply omitted then.
41	     */
42	    default String selfLink(Owner owner) {
43	        if (owner == null || owner.getId() == null) {
44	            return null;
45	        }
46	        return "/api/owners/" + owner.getId();
47	    }
48	
49	    /**
50	     * The owner's fiscal year, derived at read time and formatted {@code FY<YY>}. It references the
51	     * {@code memberId}: the two FY digits sit between the REGION prefix and the HASH8 segment, so this
52	     * reads them straight back out (2026-07-01 registration -> {@code memberId} 'NSW27...' -> {@code
53	     * FY27}). Owners predating the unified {@code memberId} (e.g. seed data) fall back to the
54	     * (business-day-adjusted) {@code registrationDate}, where the fiscal year starts on 1 July.
55	     * Null when neither source is available, so the field is simply omitted then.
56	     */
57	    default String fiscalYear(Owner owner) {
58	        if (owner == null) {
59	            return null;
60	        }
61	        String fromMember = fiscalYearFromMemberId(owner.getMemberId());
62	        if (fromMember != null) {
63	            return fromMember;
64	        }
65	        if (owner.getRegistrationDate() == null) {
66	            return null;
67	        }
68	        return String.format("FY%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
69	    }
70	
71	    /**
72	     * Reads the {@code FY<YY>} value out of the {@code memberId}: the two digits immediately after the
73	     * leading REGION letters. Null when the {@code memberId} is absent or does not have two digits in
74	     * that position. Kept {@code private static} so MapStruct does not treat it as a property mapping.
75	     */
76	    private static String fiscalYearFromMemberId(String memberId) {
77	        if (memberId == null) {
78	            return null;
79	        }
80	        int i = 0;
81	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
82	            i++;
83	        }
84	        if (i == 0 || memberId.length() < i + 2) {
85	            return null;
86	        }
87	        String yy = memberId.substring(i, i + 2);
88	        return yy.matches("[0-9]{2}") ? "FY" + yy : null;
89	    }
90	
91	    /**
92	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July, so
93	     * a date in July or later belongs to the next calendar year and an earlier date to the current
94	     * calendar year. Kept {@code private static} so MapStruct does not treat it as a property mapping.
95	     */
96	    private static int fiscalYearOf(java.time.LocalDate date) {
97	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
98	    }
99	
100	    /**
101	     * The owner's age band, derived at read time from {@code birthDate} relative to the
102	     * {@code registrationDate}: {@code MINOR} under 18, {@code ADULT} from 18 to 64 and
103	     * {@code SENIOR} at 65 or older. Null when the owner or its {@code birthDate} (or the
104	     * {@code registrationDate} it is measured against) is absent, so the field is simply
105	     * omitted for owners without a birth date.
106	     */
107	    default String ageBand(Owner owner) {
108	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
109	            return null;
110	        }
111	        int years = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
112	        if (years < 18) {
113	            return "MINOR";
114	        }
115	        if (years < 65) {
116	            return "ADULT";
117	        }
118	        return "SENIOR";
119	    }
120	
121	    /**
122	     * The owner's preferred contact channel, derived at read time: {@code EMAIL}
123	     * when an email address is present, otherwise {@code PHONE}.
124	     */
125	    default String contactPreference(Owner owner) {
126	        if (owner == null) {
127	            return null;
128	        }
129	        String email = owner.getEmail();
130	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
131	    }
132	
133	    /** Fixed city-to-region table used to derive an owner's locality at read time. */
134	    Map<String, String> CITY_REGION = Map.of(
135	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
136	
137	    /** Region to its inclusive 4-digit postcode range {low, high}. */
138	    Map<String, int[]> REGION_POSTCODES = Map.of(
139	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
140	
141	    /** Fixed region-to-timezone table, mapping each region to its IANA timezone name. */
142	    Map<String, String> REGION_TIMEZONE = Map.of(
143	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
144	
145	    /**
146	     * The owner's locality, derived at read time from the {@code memberId}: its leading REGION prefix
147	     * (the run of letters before the FY digits). That region was itself derived at write time from the
148	     * postcode (preferred) or city, defaulting to {@code UNKNOWN}, so reading it back keeps locality
149	     * and the member identity in lock-step.
150	     *
151	     * <p>Owners predating the unified {@code memberId} (e.g. seed data with no memberId) fall back to
152	     * the historical read-time derivation: postcode preferred, then city, then {@code UNKNOWN}.
153	     */
154	    default String locality(Owner owner) {
155	        if (owner == null) {
156	            return null;
157	        }
158	        String region = regionFromMemberId(owner.getMemberId());
159	        if (region != null) {
160	            return region;
161	        }
162	        String byPostcode = regionFromPostcode(owner.getPostcode());
163	        if (byPostcode != null) {
164	            return byPostcode;
165	        }
166	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
167	    }
168	
169	    /**
170	     * The leading REGION prefix of a {@code memberId}: its run of leading letters, which sits before
171	     * the two FY digits. Null when the {@code memberId} is absent or does not start with a letter.
172	     * Kept {@code private static} so MapStruct does not treat it as a property mapping method.
173	     */
174	    private static String regionFromMemberId(String memberId) {
175	        if (memberId == null || memberId.isEmpty()) {
176	            return null;
177	        }
178	        int i = 0;
179	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
180	            i++;
181	        }
182	        return i > 0 ? memberId.substring(0, i) : null;
183	    }
184	
185	    /**
186	     * The owner's segment, derived at read time and formatted {@code <TIER>_<AREA>}. TIER is
187	     * {@code PREMIUM} when the owner's {@code membershipLevel} is 3 or more, otherwise
188	     * {@code STANDARD}. AREA is {@code METRO} when the owner's {@link #locality(Owner) locality} is a
189	     * known region (NSW, VIC or QLD), otherwise {@code REGIONAL}. Null when the owner is absent.
190	     */
191	    default String ownerSegment(Owner owner) {
192	        if (owner == null) {
193	            return null;
194	        }
195	        Integer level = owner.getMembershipLevel();
196	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
197	        String area = REGION_TIMEZONE.containsKey(locality(owner)) ? "METRO" : "REGIONAL";
198	        return tier + "_" + area;
199	    }
200	
201	    /**
202	     * The owner's IANA timezone, derived at read time from the owner's locality/region via the fixed
203	     * region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane).
204	     * Null when the owner is absent or the region has no known timezone (e.g. {@code UNKNOWN}), so the
205	     * field is simply omitted then.
206	     */
207	    default String timezone(Owner owner) {
208	        if (owner == null) {
209	            return null;
210	        }
211	        return REGION_TIMEZONE.get(locality(owner));
212	    }
213	
214	    /**
215	     * The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
216	     * absent, not four digits, or in no known range. Kept {@code private static} so MapStruct does not
217	     * treat it as a {@code String}-to-{@code String} property mapping method.
218	     */
219	    private static String regionFromPostcode(String postcode) {
220	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
221	            return null;
222	        }
223	        int value = Integer.parseInt(postcode);
224	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
225	            int[] range = entry.getValue();
226	            if (value >= range[0] && value <= range[1]) {
227	                return entry.getKey();
228	            }
229	        }
230	        return null;
231	    }
232	
233	    /** Known E.164 country codes, longest first so '61' matches before the shorter '1', mirroring
234	     *  the write-time normalization in NormalizeOwnerTelephone. */
235	    List<String> COUNTRY_CODES = List.of("61", "1");
236	
237	    /**
238	     * The stored E.164 {@code telephone} formatted for humans at read time: the country code, a single
239	     * space, then the national digits grouped in threes from the left, e.g. {@code '+61412345678'} ->
240	     * {@code '+61 412 345 678'}. The raw {@code telephone} is unchanged. Null when the owner is absent;
241	     * a value that is not a recognizable E.164 string (no leading {@code '+'}, non-digits, or no known
242	     * country code) is returned unchanged.
243	     */
244	    default String telephoneDisplay(Owner owner) {
245	        if (owner == null) {
246	            return null;
247	        }
248	        String telephone = owner.getTelephone();
249	        if (telephone == null || !telephone.startsWith("+")) {
250	            return telephone;
251	        }
252	        String digits = telephone.substring(1);
253	        if (!digits.matches("[0-9]+")) {
254	            return telephone;
255	        }
256	        String countryCode = null;
257	        for (String code : COUNTRY_CODES) {
258	            if (digits.startsWith(code)) {
259	                countryCode = code;
260	                break;
261	            }
262	        }
263	        if (countryCode == null) {
264	            return telephone;
265	        }
266	        String national = digits.substring(countryCode.length());
267	        StringBuilder grouped = new StringBuilder();
268	        for (int i = 0; i < national.length(); i++) {
269	            if (i > 0 && i % 3 == 0) {
270	                grouped.append(' ');
271	            }
272	            grouped.append(national.charAt(i));
273	        }
274	        return "+" + countryCode + (grouped.length() == 0 ? "" : " " + grouped);
275	    }
276	
277	    /**
278	     * The owner's salutation, derived at read time as the stored title and last name
279	     * separated by a single space (e.g. 'DR Franklin'), or just the last name when no
280	     * title was supplied (null or blank).
281	     */
282	    default String salutation(Owner owner) {
283	        if (owner == null) {
284	            return null;
285	        }
286	        String title = owner.getTitle();
287	        if (title == null || title.isBlank()) {
288	            return owner.getLastName();
289	        }
290	        return title + " " + owner.getLastName();
291	    }
292	
293	    /** Formats the owner's stored names as 'LastName, FirstName'. */
294	    default String displayName(Owner owner) {
295	        if (owner == null) {
296	            return null;
297	        }
298	        return owner.getLastName() + ", " + owner.getFirstName();
299	    }
300	
301	    /**
302	     * The owner's initials as the upper-cased first letters of the first and last
303	     * names, dot-separated with a trailing dot, e.g. 'J.S.'.
304	     */
305	    default String initials(Owner owner) {
306	        if (owner == null) {
307	            return null;
308	        }
309	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
310	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
311	    }
312	
313	    Owner toOwner(OwnerDto ownerDto);
314	
315	    @Mapping(target = "id", ignore = true)
316	    @Mapping(target = "pets", ignore = true)
317	    @Mapping(target = "memberId", ignore = true)
318	    @Mapping(target = "householdId", ignore = true)
319	    @Mapping(target = "namesakeCount", ignore = true)
320	    @Mapping(target = "householdSize", ignore = true)
321	    @Mapping(target = "membershipPoints", ignore = true)
322	    Owner toOwner(OwnerFieldsDto ownerDto);
323	
324	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
325	
326	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
327	
328	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
329	        OwnerPageDto ownerPageDto = new OwnerPageDto();
330	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
331	        ownerPageDto.setPage(ownerPage.getNumber());
332	        ownerPageDto.setSize(ownerPage.getSize());
333	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
334	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
335	        return ownerPageDto;
336	    }
337	}
